3:type Item struct {
4:	Name     string
5:	PriceCts int
6:	Qty      int
7:}
8:
9:func Total(items []Item, discountPercent int) int {
10:	total := 0
11:	for _, it := range items {
12:		total += it.PriceCts * it.Qty
13:	}
14:	return total + total*discountPercent/100
15:}

