3:import "sort"
4:
5:func Mean(xs []int) float64 {
6:	if len(xs) == 0 {
7:		return 0
8:	}
9:	sum := 0
10:	for _, x := range xs {
11:		sum += x
12:	}
13:	return float64(sum / len(xs))
14:}
15:
16:func Median(xs []float64) float64 {
17:	if len(xs) == 0 {
18:		return 0
19:	}
20:	s := append([]float64(nil), xs...)
21:	sort.Float64s(s)
22:	n := len(s)
23:	if n%2 == 1 {
24:		return s[n/2]
25:	}
26:	return (s[n/2-1] + s[n/2]) / 2
27:}

1:package shop
2:
3:import "testing"
4:
5:func TestMean(t *testing.T) {
6:	if got := Mean([]int{1, 2}); got != 1.5 {
7:		t.Errorf("Mean([1 2]) = %v, want 1.5", got)
8:	}
9:	if got := Mean(nil); got != 0 {
10:		t.Errorf("Mean(nil) = %v, want 0", got)
11:	}
12:}
13:
14:func TestMedian(t *testing.T) {
15:	if got := Median([]float64{3, 1, 2}); got != 2 {
16:		t.Errorf("odd: got %v, want 2", got)
17:	}
18:	if got := Median([]float64{4, 1, 3, 2}); got != 2.5 {
19:		t.Errorf("even: got %v, want 2.5", got)
20:	}
21:}

